const username = $json.body.erp_username;
const password = $json.body.erp_password;

// Open ERP login page
await $page.goto(
  'https://meta-digitrading.lhike-erp.com/home',
  {
    waitUntil: 'networkidle2',
    timeout: 60000
  }
);

// Wait for login form
await $page.waitForSelector('input[name="txtusername"]', {
  timeout: 30000
});

// Fill credentials
await $page.type('input[name="txtusername"]', username, {
  delay: 50
});

await $page.type('input[name="txtpass"]', password, {
  delay: 50
});

// Submit login form
await Promise.all([
  $page.click('button[type="submit"]'),
  $page.waitForNavigation({
    waitUntil: 'networkidle2',
    timeout: 60000
  }).catch(() => null)
]);

// Check for login error
const loginError = await $page.$('.alert-danger');

if (loginError) {
  const errorText = await $page.evaluate(
    el => el.textContent.trim(),
    loginError
  );

  throw new Error(`Login failed: ${errorText}`);
}

// Optional: verify login succeeded
const currentUrl = $page.url();

if (currentUrl.includes('/login')) {
  throw new Error('Login may have failed. Still on login page.');
}

// Get cookies
const cookies = await $page.cookies();

return [
  {
    json: {
      success: true,
      currentUrl,
      cookies
    }
  }
];

