const cookies = $('Login').first().json.cookies;
const items = $input.all();

// Yesterday's date as MM/DD/YYYY
const now = new Date();
now.setDate(now.getDate() - 1);
const yesterday =
  String(now.getMonth() + 1).padStart(2, '0') + '/' +
  String(now.getDate()).padStart(2, '0') + '/' +
  now.getFullYear();

// Use webhook date if provided, otherwise yesterday
const webhookDate = $('Webhook').first().json.body.date;
const date = webhookDate || yesterday;

for (const item of items) {
  item.json.cookies = cookies;
  item.json.date = date;
}

return items;

const orders = $input.all().map(item => item.json);


return [
  {
    json: {
      orders,
    },
  },
];

const { cookies, date, columns, type = 'shipdate' } = $json;

// ---------------------------------------------------------------- config

const [mm, dd, yyyy] = (date || '').split('/');
if (!mm || !dd || !yyyy) throw new Error(`bad date input: ${JSON.stringify(date)} (expected MM/DD/YYYY)`);

const DATE_VALUE = `${yyyy}-${mm}-${dd}`;   // proven format; MM/DD/YYYY is rejected

const PRESETS = {
  orderdate: ['#sorderdate', '#eorderdate'],
  shipdate:  ['#sshipdate',  '#sshipdate2'],
};
const FILTER_TYPE = (type || '').toString().trim().toLowerCase();
if (!PRESETS[FILTER_TYPE]) {
  throw new Error(`type must be one of ${Object.keys(PRESETS).join(' | ')} — got ${JSON.stringify(type)}`);
}
const [FROM_SEL, TO_SEL] = PRESETS[FILTER_TYPE];

// Kill the automatic unfiltered draw that fires on page load. It scans all
// ~350k rows server-side and is the longest single operation in the run —
// which is exactly where browserless keeps dropping us. We never use that
// data: we issue our own filtered request instead.
const ABORT_INITIAL_DRAW = true;

const CHUNK = 1000;
const MAX_ROWS = 60000;

const WANT = Array.isArray(columns) && columns.length ? columns : [
  'Order Date', 'CSR', 'Verifier Name', 'Upsell By', 'Customer Name', 'Address',
  'Province', 'City', 'Brgy', 'Contact', 'Order', 'Total Qty', 'Price (Final)',
  'Page', 'Platform', 'Tracking No.', 'Courier', 'Parcel Status', 'Encoded Date',
  'Parcel Update', 'Shipping Fee', 'MoP', 'Order Status', 'Shipped Out Date',
  'Date Added', 'Price (Initial)', 'Price (Upsell)', 'Intern & Brands Name',
  'Total COG',
];

// ---------------------------------------------------------------- setup

let allowXhr = !ABORT_INITIAL_DRAW;
const log = [];

try {
  await $page.setRequestInterception(true);
  $page.on('request', (req) => {
    try {
      if (req.isInterceptResolutionHandled && req.isInterceptResolutionHandled()) return;
      const t = req.resourceType();
      if (t === 'image' || t === 'media' || t === 'font') return void req.abort().catch(() => {});
      if (!allowXhr && (t === 'xhr' || t === 'fetch')) return void req.abort().catch(() => {});
      req.continue().catch(() => {});
    } catch (_) {
      try { req.continue().catch(() => {}); } catch (__) {}
    }
  });
} catch (e) {
  allowXhr = true;
  log.push(`request interception unavailable: ${e?.message}`);
}

if (cookies && cookies.length) await $page.setCookie(...cookies);
await $page.setViewport({ width: 1280, height: 800 });

// ---------------------------------------------------------------- helpers

const norm = (s) => (s || '').replace(/\s+/g, ' ').trim();

function cleanCell(v) {
  if (v == null) return '';
  return String(v)
    .replace(/<br\s*\/?>/gi, ' ')
    .replace(/<[^>]*>/g, '')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/\s+/g, ' ')
    .trim();
}

async function alive() {
  try { await $page.evaluate(() => 1); return true; } catch (_) { return false; }
}

async function setField(selector, value) {
  await $page.waitForSelector(selector, { timeout: 30000 });
  await $page.evaluate((sel, val) => {
    const el = document.querySelector(sel);
    if (!el) return;
    const proto = Object.getPrototypeOf(el);
    const setter = Object.getOwnPropertyDescriptor(proto, 'value')?.set;
    setter ? setter.call(el, val) : (el.value = val);
    el.dispatchEvent(new Event('input',  { bubbles: true }));
    el.dispatchEvent(new Event('change', { bubbles: true }));
    el.dispatchEvent(new KeyboardEvent('keyup', { bubbles: true }));
    if (el.blur) el.blur();
  }, selector, value);

  const live = await $page.evaluate(sel => document.querySelector(sel)?.value ?? null, selector);
  return live === value;
}

// One filtered request straight to the DataTables endpoint.
// dt.ajax.params() runs the table's own `data` callback, which reads the
// filter inputs live — so the dates are included WITHOUT clicking search
// and WITHOUT triggering a redraw.
async function fetchChunk(start, length) {
  return await $page.evaluate(async (start, length) => {
    const jq = window.jQuery || window.$;
    const dt = jq('#tblorders').DataTable();
    const p = dt.ajax.params();
    p.start = start;
    p.length = length;

    const s = dt.settings()[0];
    const a = s.ajax;
    const url = typeof a === 'string' ? a : ((a && a.url) || s.sAjaxSource || location.href);
    const method = ((a && (a.type || a.method)) || 'POST').toUpperCase();
    const qs = jq.param(p);

    let res;
    try {
      if (method === 'GET') {
        res = await fetch(url + (url.includes('?') ? '&' : '?') + qs, {
          credentials: 'same-origin',
          headers: { 'X-Requested-With': 'XMLHttpRequest' },
        });
      } else {
        res = await fetch(url, {
          method: 'POST',
          credentials: 'same-origin',
          headers: {
            'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8',
            'X-Requested-With': 'XMLHttpRequest',
          },
          body: qs,
        });
      }
    } catch (e) {
      return { error: `fetch failed: ${e.message}`, url, method };
    }

    if (!res.ok) return { error: `HTTP ${res.status}`, url, method };

    const text = await res.text();
    try {
      const j = JSON.parse(text);
      return {
        data: j.data || j.aaData || [],
        recordsFiltered: j.recordsFiltered ?? j.recordsDisplay ?? j.iTotalDisplayRecords ?? null,
        recordsTotal: j.recordsTotal ?? j.iTotalRecords ?? null,
        titles: (s.aoColumns || []).map(c => (c.sTitle || '').replace(/<[^>]*>/g, '').trim()),
        url, method,
      };
    } catch (e) {
      return { error: 'non-JSON response', sample: text.slice(0, 300), url, method };
    }
  }, start, length);
}

function mapRow(raw, titles) {
  const obj = {};
  if (Array.isArray(raw)) {
    raw.forEach((cell, i) => { obj[titles[i] || `col_${i}`] = cleanCell(cell); });
  } else {
    for (const [k, v] of Object.entries(raw)) obj[k] = cleanCell(v);
  }
  const m = /\/view\/(\d+)/.exec(JSON.stringify(raw));
  if (m) obj.id = m[1];
  return obj;
}

function pickColumns(obj) {
  const wanted = WANT.map(w => norm(w).toLowerCase());
  const out = {};
  if (obj.id) out.id = obj.id;
  for (const [k, v] of Object.entries(obj)) {
    const key = norm(k);
    if (!key || /^col_\d+$/i.test(key) || /^(actions?|search)$/i.test(key)) continue;
    const lk = key.toLowerCase();
    if (wanted.some(w => lk === w || lk.includes(w) || w.includes(lk))) out[key] = v;
  }
  return out;
}

// ---------------------------------------------------------------- main

try {
  await $page.goto('https://meta-digitrading.lhike-erp.com/customer', {
    waitUntil: 'domcontentloaded', timeout: 60000,
  });

  // Only wait for the table object to exist. We deliberately do NOT wait for
  // it to finish drawing — with ABORT_INITIAL_DRAW its first request never
  // completes, and that draw is worthless to us anyway.
  await $page.waitForFunction(() => {
    const jq = window.jQuery || window.$;
    return !!(jq && jq.fn.dataTable && jq.fn.dataTable.isDataTable('#tblorders'));
  }, { timeout: 60000, polling: 250 });
  log.push('datatable initialised');

  // ---- set the filter fields (no click, no draw) ------------------------
  const okFrom = await setField(FROM_SEL, DATE_VALUE);
  const okTo   = await setField(TO_SEL, DATE_VALUE);
  log.push(`${FROM_SEL}=${okFrom} ${TO_SEL}=${okTo} value="${DATE_VALUE}"`);
  if (!(okFrom && okTo)) {
    throw new Error(`could not set ${FILTER_TYPE} fields to ${DATE_VALUE}`);
  }

  // ---- pull the data ----------------------------------------------------
  allowXhr = true;

  const first = await fetchChunk(0, CHUNK);
  if (first.error) {
    throw new Error(`ajax probe failed: ${first.error}${first.sample ? ` | ${first.sample}` : ''}`);
  }

  const total = first.recordsFiltered;
  log.push(`ajax ${first.method} ${first.url} -> ${total} filtered of ${first.recordsTotal}`);

  if (total == null) throw new Error('response had no recordsFiltered');
  if (first.recordsTotal != null && total === first.recordsTotal) {
    throw new Error(`${FILTER_TYPE} filter not reflected in the request — ${total} rows returned`);
  }
  if (total > MAX_ROWS) throw new Error(`${total} rows exceeds MAX_ROWS ${MAX_ROWS}`);

  const all = [];
  const seen = new Set();
  let batch = first;
  let start = 0;

  while (start < total) {
    if (batch.error) throw new Error(`chunk at ${start}: ${batch.error}`);
    const rows = batch.data || [];
    if (!rows.length) break;

    for (const raw of rows) {
      const row = mapRow(raw, batch.titles || first.titles);
      const key = row.id || JSON.stringify(raw);
      if (seen.has(key)) continue;
      seen.add(key);
      all.push(pickColumns(row));
    }

    start += rows.length;
    log.push(`fetched ${all.length}/${total}`);
    if (start >= total) break;
    batch = await fetchChunk(start, Math.min(CHUNK, total - start));
  }

  if (all.length < total) log.push(`WARNING: kept ${all.length} of ${total}`);

  return all.map(r => ({ json: { ...r, _meta: { type: FILTER_TYPE, date } } }));

} catch (err) {
  const msg = err?.message ?? 'Something went wrong';
  const sessionDied = /Target closed|detached|Session closed|disconnected|Protocol error/i.test(msg);
  const up = await alive();
  return [{
    json: {
      error: msg,
      sessionDied,
      pageAlive: up,
      hint: sessionDied
        ? 'The session is being dropped by browserless, not by this script. Raise its connection timeout (e.g. CONNECTION_TIMEOUT=300000 or ?timeout=300000 on the ws endpoint) and give the container more memory.'
        : undefined,
      url: up ? $page.url() : null,
      date, type: FILTER_TYPE, log,
    },
  }];
}

const items = $input.all();
const body = $('Webhook').first().json.body;
const webhook = body.webhook_url;
const api_key = body.workspace_api_key;
const workspace_id = body.workspace_id;

// Flatten every branch's orders into one list
let orders = items.flatMap(i => i.json.orders || []);

// Drop DataTables "No data available in table" placeholder rows
orders = orders.filter(o =>
  !Object.values(o).some(v => /no data available in table/i.test(String(v)))
);

// Dedupe on tracking number (in case an order shows under both statuses)
const seen = new Set();
orders = orders.filter(o => {
  const t = o['Tracking Number'];
  if (!t) return true;
  if (seen.has(t)) return false;
  seen.add(t);
  return true;
});

// Split into batches of 1000 — one n8n item per batch
const SIZE = 1000;
const batches = [];
for (let i = 0; i < orders.length; i += SIZE) {
  batches.push(orders.slice(i, i + SIZE));
}

const batch_id = `${workspace_id}-${new Date().toISOString().slice(0, 10)}-${Date.now()}`;

return batches.map((batch, index) => ({
  json: {
    orders: batch,
    orders_count: batch.length,
    total_count: orders.length,
    batch_index: index + 1,
    batch_total: batches.length,
    batch_id,
    webhook,
    api_key,
    workspace_id,
  },
}));

