// n8n Puppeteer node — one script for both workflows.
// Input $json: { cookies, date (MM/DD/YYYY), columns?, type: 'orderdate' | 'shipdate' }
//
// Scrapes the rendered table, so every value is already formatted exactly as
// the UI shows it (innerText), no HTML parsing.

const { cookies, date, columns, type = 'orderdate' } = $json;

// ---------------------------------------------------------------- config

const [mm, dd, yyyy] = (date || '').split('/');
if (!mm || !dd || !yyyy) throw new Error(`bad date input: ${JSON.stringify(date)} (expected MM/DD/YYYY)`);

// orderdate pickers accept MM/DD/YYYY; shipdate pickers only accept YYYY-MM-DD.
// A format that won't stick in the field is skipped WITHOUT clicking search —
// that skip is what stops shipdate from wasting a full 350k-row scan.
const DATE_FORMATS = [`${mm}/${dd}/${yyyy}`, `${yyyy}-${mm}-${dd}`, `${dd}/${mm}/${yyyy}`];

const PRESETS = {
  orderdate: ['#sorderdate', '#eorderdate'],
  shipdate:  ['#sshipdate',  '#sshipdate2'],
};
const FILTER_TYPE = (type || '').toString().trim().toLowerCase();
if (!PRESETS[FILTER_TYPE]) {
  throw new Error(`type must be one of ${Object.keys(PRESETS).join(' | ')} — got ${JSON.stringify(type)}`);
}
const [FROM_SEL, TO_SEL] = PRESETS[FILTER_TYPE];

const PAGE_LEN = 300;        // 7,009 shipdate rows -> 24 draws instead of 71
const MAX_PAGES = 60;
const DRAW_TIMEOUT = 120000; // the first unfiltered draw scans ~350k rows

const WANT = Array.isArray(columns) && columns.length ? columns : [
  'Order ID', 'Order Date', 'CSR', 'Verifier Name', 'Upsell By', 'Customer Name',
  'Address', 'Province', 'City', 'Brgy', 'Contact', 'Order', 'Total Qty',
  'Price (Final)', 'Page', 'Platform', 'Tracking No.', 'Courier', 'Parcel Status',
  'Encoded Date', 'Parcel Update', 'Shipping Fee', 'MoP', 'Order Status',
  'Shipped Out Date', 'Date Added', 'Price (Initial)', 'Price (Upsell)',
  'Intern & Brands Name', 'Total COG',
];

let wantIdx = [];
let wantNameOnly = WANT;

const log = [];
const attempts = [];

// drop images/fonts — pure overhead, and the container is memory-tight
try {
  await $page.setRequestInterception(true);
  $page.on('request', (req) => {
    try {
      if (req.isInterceptResolutionHandled && req.isInterceptResolutionHandled()) return;
      const t = req.resourceType();
      if (t === 'image' || t === 'media' || t === 'font') req.abort().catch(() => {});
      else req.continue().catch(() => {});
    } catch (_) {
      try { req.continue().catch(() => {}); } catch (__) {}
    }
  });
} catch (e) {
  log.push(`interception unavailable: ${e?.message}`);
}

if (cookies && cookies.length) await $page.setCookie(...cookies);
await $page.setViewport({ width: 1280, height: 800 });

// ---------------------------------------------------------------- helpers

async function alive() {
  try { await $page.evaluate(() => 1); return true; } catch (_) { return false; }
}

async function snap(name) {
  try {
    const data = await $page.screenshot({ encoding: 'base64', fullPage: false });
    return { [name]: { data, mimeType: 'image/png', fileName: `${name}.png`, fileExtension: 'png' } };
  } catch (_) { return {}; }
}

async function armDraw() {
  const ok = await $page.evaluate(() => {
    const jq = window.jQuery || window.$;
    if (!(jq && jq.fn.dataTable && jq.fn.dataTable.isDataTable('#tblorders'))) return false;
    window.__drawn = false;
    jq('#tblorders').DataTable().one('draw.dt', () => { window.__drawn = true; });
    return true;
  });
  if (!ok) throw new Error('#tblorders is not an initialised DataTable');
}

async function waitDraw(timeout = DRAW_TIMEOUT) {
  await $page.waitForFunction(() => window.__drawn === true, { timeout, polling: 500 });
}

async function tableInfo() {
  return await $page.evaluate(() => {
    const jq = window.jQuery || window.$;
    return jq('#tblorders').DataTable().page.info();
  });
}

// read the real name -> data-column map off the toggle pills
async function buildColMap() {
  return await $page.evaluate(() => {
    const n = (s) => (s || '').replace(/\s+/g, ' ').trim();
    const out = {};
    document.querySelectorAll('[data-column]').forEach(el => {
      const name = n(el.innerText);
      const idx = parseInt(el.getAttribute('data-column'), 10);
      if (name && Number.isInteger(idx) && !(name in out)) out[name] = idx;
    });
    return out;
  });
}

async function setField(selector, value) {
  const tag = await $page.evaluate((sel) => {
    const el = document.querySelector(sel);
    return el ? el.tagName.toLowerCase() : null;
  }, selector);
  if (tag === 'select') { await $page.select(selector, value); return true; }

  await $page.evaluate((sel, val) => {
    const el = document.querySelector(sel);
    if (!el) return;
    const proto = Object.getPrototypeOf(el);
    const setter = Object.getOwnPropertyDescriptor(proto, 'value')?.set;
    setter ? setter.call(el, val) : (el.value = val);
    el.dispatchEvent(new Event('input',  { bubbles: true }));
    el.dispatchEvent(new Event('change', { bubbles: true }));
    el.dispatchEvent(new KeyboardEvent('keyup', { bubbles: true }));
    if (el.blur) el.blur();
  }, selector, value);

  let live = await $page.evaluate(sel => document.querySelector(sel)?.value ?? null, selector);
  if (live === value) return true;

  try {
    await $page.click(selector, { clickCount: 3 });
    await $page.keyboard.press('Backspace');
    await $page.type(selector, value, { delay: 25 });
    await $page.keyboard.press('Escape');
    live = await $page.evaluate(sel => document.querySelector(sel)?.value ?? null, selector);
  } catch (_) {}
  return live === value;
}

async function selectColumns(idxArr, nameArr) {
  await armDraw();
  await $page.evaluate((idxs, names) => {
    const n = (s) => (s || '').replace(/\s+/g, ' ').trim().toLowerCase();
    const idxSet = new Set(idxs);
    const want = names.map(n).filter(Boolean);
    const jq = window.jQuery || window.$;
    const dt = jq('#tblorders').DataTable();

    dt.columns().every(function () {
      const idx = this.index();
      const th = this.header();
      const text = n(th ? th.innerText : '');
      let hasViewLink = false;
      try {
        const nodes = this.nodes();
        for (let i = 0; i < nodes.length; i++) {
          if (nodes[i].querySelector && nodes[i].querySelector('a[href*="/view/"]')) { hasViewLink = true; break; }
        }
      } catch (_) {}
      const keep = idxSet.has(idx)
                   || want.some(w => text === w || text.includes(w))
                   || text === '' || text === 'no' || text === '#' || text === 'actions'
                   || hasViewLink;
      this.visible(keep, false);
    });
    dt.columns.adjust().draw(false);
  }, idxArr, nameArr);
  await waitDraw();
}

// innerText — values come out exactly as rendered in the UI
async function extractTable() {
  return await $page.evaluate(() => {
    const table = document.querySelector('#tblorders') || document.querySelector('table');
    if (!table) return [];
    const headers = Array.from(table.querySelectorAll('thead th')).map(th => {
      const c = th.cloneNode(true);
      c.querySelectorAll('select, input, textarea, button').forEach(x => x.remove());
      return c.innerText.trim();
    });
    return Array.from(table.querySelectorAll('tbody tr')).map(tr => {
      const cells = Array.from(tr.querySelectorAll('td'));
      if (!cells.length) return null;
      const obj = {};
      cells.forEach((td, i) => { obj[headers[i] || `col_${i}`] = td.innerText.trim(); });
      const link = tr.querySelector('a[href*="/view/"]');
      if (link) {
        const m = link.getAttribute('href').match(/\/view\/(\d+)/);
        if (m) obj.id = m[1];
      }
      return obj;
    }).filter(Boolean);
  });
}

function normalize(row) {
  const out = {};
  for (const [rawKey, value] of Object.entries(row)) {
    const key = (rawKey || '').trim();
    if (!key) continue;
    if (/^col_\d+$/i.test(key)) continue;
    if (/[\n\r]/.test(key)) continue;
    if (/^(actions?|search)$/i.test(key)) continue;
    out[key] = value;
  }
  return out;
}

// ---------------------------------------------------------------- main

try {
  await $page.goto('https://meta-digitrading.lhike-erp.com/customer', {
    waitUntil: 'domcontentloaded', timeout: 60000,
  });

  await $page.waitForFunction(() => {
    const jq = window.jQuery || window.$;
    return !!(jq && jq.fn.dataTable && jq.fn.dataTable.isDataTable('#tblorders'));
  }, { timeout: 60000, polling: 250 });
  log.push(`datatable ready, type=${FILTER_TYPE}`);

  // The filter panel only renders once the first draw lands, and that draw
  // scans the whole table — so wait on the FIELD, generously.
  try {
    await $page.waitForSelector(FROM_SEL, { timeout: DRAW_TIMEOUT });
    await $page.waitForSelector(TO_SEL,   { timeout: 30000 });
  } catch (_) {
    const ids = await $page.evaluate(() =>
      Array.from(document.querySelectorAll('input[id]')).map(el => '#' + el.id));
    throw new Error(`${FROM_SEL} / ${TO_SEL} never rendered. Inputs present: ${JSON.stringify(ids)}`);
  }
  log.push('filter panel rendered');

  const colMap = await buildColMap();
  wantIdx = WANT.map(n => colMap[n]).filter(i => i !== undefined);
  wantNameOnly = WANT.filter(n => colMap[n] === undefined);
  log.push(`columns: ${wantIdx.length} by index, ${wantNameOnly.length} by name`);

  const baseline = await tableInfo();
  log.push(`baseline ${baseline.recordsTotal} rows`);

  // ---- filter -----------------------------------------------------------
  let info = null, usedFormat = null;

  for (const val of DATE_FORMATS) {
    const okFrom = await setField(FROM_SEL, val);
    const okTo   = await setField(TO_SEL, val);

    if (!(okFrom && okTo)) {
      attempts.push({ value: val, setOk: false, skipped: true });
      log.push(`"${val}" rejected by the picker — search skipped`);
      continue;
    }

    await armDraw();
    await $page.click('a#btndtsearch');
    await waitDraw();

    const i2 = await tableInfo();
    attempts.push({ value: val, setOk: true, recordsDisplay: i2.recordsDisplay });
    log.push(`"${val}" -> ${i2.recordsDisplay} rows`);

    if (i2.recordsDisplay < baseline.recordsTotal) { info = i2; usedFormat = val; break; }
  }

  if (!usedFormat) {
    return [{
      json: { error: `${FILTER_TYPE} filter never applied — still ${baseline.recordsTotal} rows`,
              url: $page.url(), date, type: FILTER_TYPE, attempts, log },
      binary: await snap('filter-failed'),
    }];
  }

  // ---- columns FIRST, then page length ----------------------------------
  // Enlarging pages while all ~35 columns are visible renders 300 x 35 cells
  // per draw. Hiding first cuts that substantially.
  await selectColumns(wantIdx, wantNameOnly);

  await armDraw();
  await $page.evaluate((len) => {
    const jq = window.jQuery || window.$;
    jq('#tblorders').DataTable().page.len(len).draw('page');
  }, PAGE_LEN);
  await waitDraw();

  info = await tableInfo();
  log.push(`${info.recordsDisplay} rows over ${info.pages} pages @ ${PAGE_LEN}`);
  if (info.pages > MAX_PAGES) {
    throw new Error(`${info.pages} pages (${info.recordsDisplay} rows) — refusing to paginate`);
  }

  // ---- paginate ---------------------------------------------------------
  const all = [];
  const seen = new Set();

  for (let p = 0; p < info.pages; p++) {
    if (p > 0) {
      await armDraw();
      await $page.evaluate(() => {
        const jq = window.jQuery || window.$;
        jq('#tblorders').DataTable().page('next').draw('page');
      });
      await waitDraw();
    }

    const rows = await extractTable();
    if (!rows.length) throw new Error(`page ${p + 1}/${info.pages} came back empty`);

    for (const raw of rows) {
      const key = raw.id ?? JSON.stringify(raw);
      if (seen.has(key)) continue;
      seen.add(key);
      all.push(normalize(raw));
    }
    log.push(`page ${p + 1}/${info.pages} -> ${all.length}`);
  }

  if (all.length < info.recordsDisplay) {
    throw new Error(`scraped ${all.length} of ${info.recordsDisplay} rows`);
  }

  log.push(`done: ${all.length} rows via "${usedFormat}"`);
  return all.map(r => ({ json: { ...r, _meta: { type: FILTER_TYPE, date, usedFormat } } }));

} catch (err) {
  const msg = err?.message ?? 'Something went wrong';
  const sessionDied = /Target closed|detached|Session closed|disconnected|Protocol error/i.test(msg);
  const up = await alive();
  return [{
    json: {
      error: msg, sessionDied, pageAlive: up,
      hint: sessionDied ? 'browserless dropped the session — raise CONNECTION_TIMEOUT and container memory' : undefined,
      url: up ? $page.url() : null,
      date, type: FILTER_TYPE, attempts, log,
    },
    binary: up ? await snap('error') : {},
  }];
}
